/* part:page.script.preview.kit.signature-pad */
/* The catalog's live preview of kit.signature-pad. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect, useRef } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const Sim = ({ children }) => html`<p class="pv-sim"><b>Sandbox</b> ${children}</p>`;
const Cases = ({ d, value, set, label = 'Use case' }) => html`<div class="pv-row" role="group" aria-label=${label}><span class="pv-label">${label}</span>
  ${d.cases.map(c => html`<button type="button" key=${c.id} class=${'pv-btn' + (c.id === value ? ' pri' : '')} aria-pressed=${c.id === value} onClick=${() => set(c.id)}>${c.label}</button>`)}</div>`;
const OUT = 'background:#fff;border:1px dashed var(--rule);border-radius:8px;min-height:70px;display:flex;align-items:center;justify-content:center;padding:8px';

P['kit.signature-pad'] = ({ samples }) => {
  const d = first(samples, 'signature-pad');
  const [id, setId] = useState(d.cases[0].id);
  const c = d.cases.find(x => x.id === id);
  const host = useRef(null);
  const [out, setOut] = useState({});
  useEffect(() => {
    setOut({});
    const pads = c.boxes.map(b => K().signaturePad.mount(host.current.querySelector(`[data-box="${b.id}"]`), { label: b.label, caption: b.caption, height: b.height,
      onChange: p => setOut(o => ({ ...o, [b.id]: p.isEmpty() ? null : { png: p.toPNG(), strokes: p.toJSON().strokes.length } })) }));
    return () => pads.forEach(p => p.destroy());
  }, [id]);
  return html`<div class="pv-stack">
    <${Cases} d=${d} value=${id} set=${setId}/>
    <${Sim}>${c.context} The page binds each PNG to <code>${c.bind}</code>; the kit only draws and exports.<//>
    <div class="pv-two">
      <section ref=${host}>${c.boxes.map(b => html`<div key=${id + b.id}><p class="pv-label">${b.label}</p><div data-box=${b.id}></div></div>`)}</section>
      <section>${c.boxes.map(b => html`<div key=${id + b.id}><p class="pv-label">${b.label}: toPNG()</p>
        <div style=${OUT}>${out[b.id] ? html`<img style="max-width:100%;max-height:160px" src=${out[b.id].png} alt=${b.label + ' as exported'}/>` : html`<span class="pv-label">empty: toPNG() gives null</span>`}</div>
        ${out[b.id] ? html`<p class="pv-label">${out[b.id].strokes} stroke(s) kept as data</p>` : ''}</div>`)}</section>
    </div></div>`;
};
})();
/* /part:page.script.preview.kit.signature-pad */

