/* part:page.style.kit.signature-pad */
/* Kit css: Signature pad    kit version 0.1.0    pairs with kit/signature-pad.js
   The signing box stays white in both themes: ink on paper is what gets exported, and the PNG is on white.
   Needs from the board: --panel --ink-2 --ink-3 --rule --f-ui; --radius optional. */
.kit-sig { position: relative; display: grid; gap: 6px; min-width: 0; }
.kit-sig-canvas { display: block; width: 100%; height: var(--kit-sig-h, 180px); background: #fff; border: 1px solid var(--rule);
  border-radius: var(--radius, 4px); cursor: crosshair; touch-action: none; }
.kit-sig-canvas:focus-visible { outline: 2px solid var(--accent, currentColor); outline-offset: 2px; }
.kit-sig-base { position: absolute; left: 16px; right: 16px; top: calc(var(--kit-sig-h, 180px) * .72); height: 0;
  border-top: 1px dashed #9a9488; pointer-events: none; }
.kit-sig-base::before { content: "×"; position: absolute; left: 0; bottom: 2px; color: #9a9488; font: 18px/1 var(--f-ui); }
.kit-sig-foot { display: flex; align-items: center; gap: 10px; font: 13px/1.4 var(--f-ui); color: var(--ink-3); }
.kit-sig-cap { flex: 1; min-width: 0; }
.kit-sig-clear { font: inherit; color: var(--ink-2); background: var(--panel); border: 1px solid var(--rule); border-radius: var(--radius, 4px);
  padding: 3px 10px; cursor: pointer; }
.kit-sig:not(.kit-sig-inked) .kit-sig-clear { visibility: hidden; }
/* /part:page.style.kit.signature-pad */

/**
 * Signature pad
 * Kit.signaturePad.mount(el, opts) draws a signing box in el: a canvas with a baseline and a caption, and a Clear button. It takes a finger, pen or mouse through pointer events (no scrolling while drawing), keeps the strokes as data, redraws them when the box is resized, and gives the result as a PNG trimmed to the ink on a white ground, or as stroke JSON. Kit.signaturePad.create(canvas, opts) is the same engine on a canvas you already have.
 *
 * What it is: the drawing surface for a signature or initials on a phone or a desktop. It records points, not pixels, so a resize or a rotation of the phone loses nothing,
 * and a stroke can be replayed. It decides nothing about what a signature means: bind the PNG to the text it signs (a content hash) in the page that uses it.
 * API (small and stable):
 *   Kit.signaturePad.mount(el, {label, caption, height, ink, onChange}) -> pad     builds .kit-sig in el: the box, the baseline, the caption and a Clear button
 *   Kit.signaturePad.create(canvas, {ink, width, onChange}) -> pad                 the engine alone on a canvas element
 *   pad.isEmpty() -> boolean          true until the first stroke
 *   pad.clear()                       forget every stroke
 *   pad.toPNG({trim = true, pad = 12, background = '#fff'}) -> data URL or null (null when empty)
 *   pad.toJSON() -> {w, h, strokes: [[[x, y, t], ...], ...]}   points in CSS pixels of the box, t in ms from the first point
 *   pad.fromJSON(data)                replay strokes (scaled to the box)
 *   pad.destroy()                     remove listeners (mount also removes its markup)
 * The ink colour defaults to a dark blue-black that reads as ink on paper and prints well; it is a drawing colour, not a theme token.
 *
 * @id        kit.signature-pad
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.1.1
 * @updated   2026-11-20
 * @summary   A box to sign or initial with a finger, pen or mouse: strokes kept as data, redrawn on resize, exported as a trimmed PNG on white or as stroke JSON.
 * @tags      signature, initials, sign, canvas, pointer, touch, pen, consent, delivery, contract, png
 * @requires  none
 * @files     kit/signature-pad.css, kit/samples/signature-pad.json, kit/previews/signature-pad.js
 * @provides  Kit.signaturePad.mount, Kit.signaturePad.create
 * @config    Kit.signaturePad.mount(el, opts) | label (aria label, default "Signature"), caption (under the baseline), height (px, default 180), ink (CSS colour), onChange(pad)
 * @config    Kit.signaturePad.create(canvas, opts) | ink, width (stroke px, default 2.4), onChange(pad)
 * @tokens    --panel --ink-2 --ink-3 --rule --f-ui --radius?
 * @globals   none
 * @db        none
 * @source    Catalog harvest, 2026-11-19 | an agreement review board's signer page | the initials and signature boxes
 * @preview   {"render": "kit.signature-pad", "samples": ["kit/samples/signature-pad.json"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
const INK = '#10204a';

function create(canvas, opts = {}) {
  const ctx = canvas.getContext('2d');
  const ink = opts.ink || INK, width = opts.width || 2.4;
  let strokes = [], cur = null, t0 = 0, box = { w: 0, h: 0 };
  canvas.style.touchAction = 'none';

  function fit() {
    const r = canvas.getBoundingClientRect(), dpr = window.devicePixelRatio || 1;
    if (!r.width || !r.height) return;
    const old = { ...box };
    box = { w: r.width, h: r.height };
    canvas.width = Math.round(r.width * dpr); canvas.height = Math.round(r.height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (old.w && (old.w !== box.w || old.h !== box.h)) {
      const sx = box.w / old.w, sy = box.h / old.h;
      strokes = strokes.map(s => s.map(([x, y, t]) => [x * sx, y * sy, t]));
    }
    paint();
  }
  function line(s) {
    ctx.strokeStyle = ink; ctx.fillStyle = ink; ctx.lineWidth = width; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    if (s.length === 1) { ctx.beginPath(); ctx.arc(s[0][0], s[0][1], width / 2, 0, Math.PI * 2); ctx.fill(); return; }
    ctx.beginPath(); ctx.moveTo(s[0][0], s[0][1]);
    for (let i = 1; i < s.length - 1; i++) { // smoothed through midpoints
      const mx = (s[i][0] + s[i + 1][0]) / 2, my = (s[i][1] + s[i + 1][1]) / 2;
      ctx.quadraticCurveTo(s[i][0], s[i][1], mx, my);
    }
    const l = s[s.length - 1]; ctx.lineTo(l[0], l[1]); ctx.stroke();
  }
  function paint() { ctx.clearRect(0, 0, box.w, box.h); strokes.forEach(line); }
  const pos = e => { const r = canvas.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top, t0 ? Math.round(performance.now() - t0) : 0]; };
  const changed = () => opts.onChange && opts.onChange(api);

  function down(e) {
    if (e.button > 0) return;
    if (!t0) t0 = performance.now();
    cur = [pos(e)]; strokes.push(cur);
    try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
    paint(); e.preventDefault();
  }
  function move(e) { if (!cur) return; cur.push(pos(e)); paint(); e.preventDefault(); }
  function up() { if (!cur) return; cur = null; changed(); }
  canvas.addEventListener('pointerdown', down);
  canvas.addEventListener('pointermove', move);
  ['pointerup', 'pointercancel'].forEach(t => canvas.addEventListener(t, up));
  const ro = window.ResizeObserver ? new ResizeObserver(fit) : null;
  if (ro) ro.observe(canvas); else window.addEventListener('resize', fit);
  fit();

  const api = {
    isEmpty: () => strokes.length === 0,
    clear() { strokes = []; t0 = 0; paint(); changed(); },
    toJSON: () => ({ w: box.w, h: box.h, strokes: strokes.map(s => s.map(p => p.slice())) }),
    fromJSON(d) {
      const sx = d && d.w ? box.w / d.w : 1, sy = d && d.h ? box.h / d.h : 1;
      strokes = ((d && d.strokes) || []).map(s => s.map(([x, y, t]) => [x * sx, y * sy, t || 0]));
      paint(); changed();
    },
    toPNG({ trim = true, pad = 12, background = '#fff' } = {}) {
      if (!strokes.length) return null;
      let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
      strokes.flat().forEach(([x, y]) => { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); });
      if (!trim) { x0 = 0; y0 = 0; x1 = box.w; y1 = box.h; pad = 0; }
      const scale = 2, w = Math.ceil(x1 - x0 + pad * 2 + width), h = Math.ceil(y1 - y0 + pad * 2 + width);
      const out = document.createElement('canvas'); out.width = w * scale; out.height = h * scale;
      const o = out.getContext('2d'); o.scale(scale, scale);
      if (background) { o.fillStyle = background; o.fillRect(0, 0, w, h); }
      o.translate(pad - x0 + width / 2, pad - y0 + width / 2);
      const draw = s => { o.strokeStyle = ink; o.fillStyle = ink; o.lineWidth = width; o.lineCap = 'round'; o.lineJoin = 'round';
        if (s.length === 1) { o.beginPath(); o.arc(s[0][0], s[0][1], width / 2, 0, Math.PI * 2); o.fill(); return; }
        o.beginPath(); o.moveTo(s[0][0], s[0][1]);
        for (let i = 1; i < s.length - 1; i++) o.quadraticCurveTo(s[i][0], s[i][1], (s[i][0] + s[i + 1][0]) / 2, (s[i][1] + s[i + 1][1]) / 2);
        o.lineTo(s[s.length - 1][0], s[s.length - 1][1]); o.stroke(); };
      strokes.forEach(draw);
      return out.toDataURL('image/png');
    },
    destroy() {
      canvas.removeEventListener('pointerdown', down); canvas.removeEventListener('pointermove', move);
      ['pointerup', 'pointercancel'].forEach(t => canvas.removeEventListener(t, up));
      if (ro) ro.disconnect(); else window.removeEventListener('resize', fit);
    },
    canvas,
  };
  return api;
}

function mount(el, opts = {}) {
  const wrap = document.createElement('div'); wrap.className = 'kit-sig';
  wrap.style.setProperty('--kit-sig-h', (opts.height || 180) + 'px');
  const canvas = document.createElement('canvas'); canvas.className = 'kit-sig-canvas';
  canvas.setAttribute('role', 'img'); canvas.setAttribute('aria-label', opts.label || 'Signature');
  const base = document.createElement('div'); base.className = 'kit-sig-base'; base.setAttribute('aria-hidden', 'true'); base.textContent = '×';
  const foot = document.createElement('div'); foot.className = 'kit-sig-foot';
  const cap = document.createElement('span'); cap.className = 'kit-sig-cap'; cap.textContent = opts.caption || 'Sign above the line';
  const btn = document.createElement('button'); btn.type = 'button'; btn.className = 'kit-sig-clear'; btn.textContent = 'Clear';
  foot.append(cap, btn); wrap.append(canvas, base, foot); el.append(wrap);
  const pad = create(canvas, { ink: opts.ink, width: opts.width, onChange: p => { wrap.classList.toggle('kit-sig-inked', !p.isEmpty()); opts.onChange && opts.onChange(p); } });
  btn.addEventListener('click', () => pad.clear());
  const destroy = pad.destroy;
  pad.destroy = () => { destroy(); wrap.remove(); };
  pad.el = wrap;
  return pad;
}

Kit.signaturePad = Object.freeze({ mount, create });
})();
